#!/usr/bin/env python3
"""Plot experiment results generated by run_experiments.sh (no synthetic values)."""
import argparse
import csv
from collections import defaultdict
from pathlib import Path
import matplotlib.pyplot as plt

parser = argparse.ArgumentParser()
parser.add_argument('--input', default='results/csv/comparison_results.csv')
parser.add_argument('--output-dir', default='results/plots')
args = parser.parse_args()
source = Path(args.input)
out = Path(args.output_dir)
if not source.is_file():
    raise SystemExit(f'CSV not found: {source}; run scripts/run_experiments.sh first')
groups = defaultdict(list)
with source.open(newline='') as f:
    for row in csv.DictReader(f):
        groups[(row['mode'], float(row['anomalyRate']))].append(row)
if not groups:
    raise SystemExit(f'No result rows in {source}')
out.mkdir(parents=True, exist_ok=True)
plots = [
    ('energyConsumed', 'Energy consumed (J)', 'energy_vs_anomaly_rate.png'),
    ('pdr', 'Packet delivery ratio', 'pdr_vs_anomaly_rate.png'),
    ('averageDelay', 'Average delay (s)', 'delay_vs_anomaly_rate.png'),
    ('throughput', 'Throughput (bit/s)', 'throughput_vs_anomaly_rate.png'),
    ('remainingEnergy', 'Remaining energy (J)', 'remaining_energy_vs_anomaly_rate.png'),
    ('anomalyDeliveryRatio', 'Anomaly delivery ratio', 'anomaly_delivery_vs_anomaly_rate.png'),
]
for metric, ylabel, filename in plots:
    fig, ax = plt.subplots(figsize=(7.2, 4.6))
    for mode in ('baseline', 'proposed'):
        rates = sorted(rate for m, rate in groups if m == mode)
        if not rates:
            continue
        means = [sum(float(row[metric]) for row in groups[(mode, rate)]) / len(groups[(mode, rate)]) for rate in rates]
        ax.plot([100*r for r in rates], means, marker='o', linewidth=2, label=mode.title())
    ax.set_xlabel('Configured anomaly rate (%)')
    ax.set_ylabel(ylabel)
    ax.grid(True, alpha=0.3)
    ax.legend()
    fig.tight_layout()
    fig.savefig(out / filename, dpi=160)
    plt.close(fig)
    print(out / filename)
